122	
123	### Custom frontmatter template via plugin
124	
125	```ts
126	const customFrontmatter: PersonaBuildPlugin = {
127	  name: 'custom-frontmatter',
128	
129	  frontmatterTemplates: {
130	    'claude-code': `---
131	name: {{cc_file_name_stem}}
132	description: '{{description}}'
133	permissionMode: {{cc_permission_mode}}
134	model: {{cc_model}}
135	memory: {{cc_memory}}
136	mcpServers:
137	  - central_pm
138	---`,
139	  },
140	};
141	```
142	
143	### Validation plugin
144	
145	```ts
146	import type { PersonaBuildPlugin, ValidationResult } from '@mistralys/persona-builder';
147	
148	const requiredFieldsPlugin: PersonaBuildPlugin = {
149	  name: 'required-fields',
150	
151	  onValidate(persona): ValidationResult[] {
152	    const errors: ValidationResult[] = [];
153	    if (!persona.description) {
154	      errors.push({ severity: 'error', message: `${persona.name}: missing "description" field` });
155	    }
156	    if (!persona.version) {
157	      errors.push({ severity: 'warning', message: `${persona.name}: missing "version" field` });
158	    }
159	    return errors;
160	  },
161	};
162	```
163	
164	### Reading `personaMode` in a plugin
165	
166	`personaMode` is a free-form string set per suite in `SuiteConfig`. The library does not
167	interpret it — it is your plugin's signal to change behaviour based on which suite is
168	being built.
169	
170	```ts
171	import type { PersonaBuildPlugin } from '@mistralys/persona-builder';
172	
173	const modeAwarePlugin: PersonaBuildPlugin = {
174	  name: 'mode-aware',
175	
176	  onSuiteInit(suite) {
177	    // Called once per suite before any persona is built.
178	    // suite.personaMode is whatever was set in SuiteConfig.personaMode.
179	    if (suite.personaMode === 'numbered') {
180	      console.log('Building numbered workflow suite');
181	    }
182	  },
183	
184	  onBuildContext(context, persona, suite) {
185	    if (suite.personaMode === 'numbered') {
186	      // Inject a mode-specific variable only for numbered suites
187	      return { ...context, workflow_mode: 'numbered' };
188	    }
189	    return context;
190	  },
191	};
192	```
193	
194	Known mode values are entirely plugin-defined. The library imposes no constraints on the
195	string value — you choose the convention that suits your project.
196	
